// Robust Normalization & Safety Fallbacks
const items = $input.all();
const results = [];

for (const item of items) {
  const row = item.json;

  // Support both direct object responses and Apify dataset wrappers
  const domain = row.domain || row.website || 'unknown';
  const techStack = Array.isArray(row.tech_stack) ? row.tech_stack : (Array.isArray(row.technologies) ? row.technologies : []);
  const hiring = row.hiring_intent || {
    is_hiring: Boolean(row.is_hiring),
    active_count: row.active_job_count || (row.open_roles ? row.open_roles.length : 0),
    open_roles: Array.isArray(row.open_roles) ? row.open_roles : [],
    growth_departments: Array.isArray(row.growth_departments) ? row.growth_departments : []
  };
  const googleAds = row.google_ads || {
    has_active_ads: Boolean(row.has_active_google_ads || row.has_active_ads),
    ad_count: row.ad_count || 0,
    target_keywords: Array.isArray(row.target_keywords) ? row.target_keywords : []
  };

  results.push({
    json: {
      ...row,
      normalized_domain: domain.toLowerCase().replace(/^https?:\/\//, '').replace(/\/.*$/, ''),
      tech_stack: techStack,
      hiring_intent: hiring,
      google_ads: googleAds,
      enrichment_provider: "HirePulse (via Apify)"
    }
  });
}

return results;

// Deterministic Intent Pre-Filter & Token Economics Engine
const items = $input.all();
const evaluatedItems = [];

// Criteria parameters for your Ideal Customer Profile (ICP)
const TARGET_KEYWORDS_TECH = ["react", "next.js", "typescript", "aws", "gcp", "hubspot", "segment", "stripe", "cloudflare", "postgresql"];
const MIN_SCORE_TO_QUALIFY = 50;

for (const item of items) {
  const lead = item.json;
  const techStack = lead.tech_stack || [];
  const hiring = lead.hiring_intent || {};
  const ads = lead.google_ads || {};

  let score = 0;
  const matches = [];
  const disqualifiers = [];

  // 1. Tech Stack Evaluation (35 Points Max)
  const matchedTech = techStack.filter(t => 
    TARGET_KEYWORDS_TECH.some(k => String(t).toLowerCase().includes(k))
  );
  if (matchedTech.length >= 3) {
    score += 35;
    matches.push(`Enterprise modern tech stack (${matchedTech.slice(0, 3).join(', ')})`);
  } else if (matchedTech.length >= 1) {
    score += 20;
    matches.push(`Relevant tech present (${matchedTech[0]})`);
  } else {
    disqualifiers.push('No modern SaaS/Cloud tech stack detected');
  }

  // 2. Hiring Intent & Growth Velocity (40 Points Max)
  const openCount = hiring.active_count || (hiring.open_roles ? hiring.open_roles.length : 0);
  if (hiring.is_hiring || openCount > 0) {
    score += 40;
    matches.push(`Active hiring velocity (${openCount} open positions)`);
  } else {
    disqualifiers.push('Zero hiring signals; team appears stagnant or downsizing');
  }

  // 3. Paid Budget & Search Intent (25 Points Max)
  if (ads.has_active_ads || (ads.target_keywords && ads.target_keywords.length > 0)) {
    score += 25;
    matches.push(`Active Google Ads budget confirmed (${ads.target_keywords.slice(0, 2).join(', ') || 'Running campaigns'})`);
  }

  const isQualified = score >= MIN_SCORE_TO_QUALIFY;
  const tier = score >= 75 ? 'TIER_1_VIP' : (score >= 50 ? 'TIER_2_QUALIFIED' : 'DISQUALIFIED');

  // 4. Token Economics Calculation:
  // Crawling raw HTML DOM: ~15,000 to 25,000 prompt tokens per page
  // Compact HirePulse JSON: ~350 prompt tokens
  // Savings: ~14,650 tokens (97.6% reduction in LLM context per lead!)
  const rawTokensBenchmark = 15000;
  const compactTokensUsed = 350;
  const tokensSaved = rawTokensBenchmark - compactTokensUsed;

  evaluatedItems.push({
    json: {
      ...lead,
      icp_score: score,
      icp_tier: tier,
      qualification_status: isQualified ? 'QUALIFIED' : 'DISQUALIFIED',
      qualification_reasons: matches,
      disqualification_reasons: disqualifiers,
      token_metrics: {
        benchmark_raw_tokens: rawTokensBenchmark,
        compact_json_tokens: compactTokensUsed,
        tokens_saved_per_lead: tokensSaved,
        token_reduction_pct: "97.6%"
      },
      filtered_at: new Date().toISOString()
    }
  });
}

return evaluatedItems;

