// Parse AI JSON output & construct production CRM row
const items = $input.all();
const crmRecords = [];

for (const item of items) {
  const row = item.json;
  let aiSubject = "Question regarding " + (row.company_name || "your stack");
  let aiBody = "Hi " + (row.contact_name ? row.contact_name.split(' ')[0] : 'there') + ", noticed your recent engineering expansion.";

  // Parse response safely
  try {
    const rawResponse = row.message?.content || row.response || "";
    const cleanJson = rawResponse.replace(/```json/g, '').replace(/```/g, '').trim();
    const parsed = JSON.parse(cleanJson);
    if (parsed.email_subject) aiSubject = parsed.email_subject;
    if (parsed.email_body) aiBody = parsed.email_body;
  } catch (err) {
    if (row.message?.content) aiBody = row.message.content;
  }

  crmRecords.push({
    json: {
      lead_domain: row.domain,
      company_name: row.company_name,
      contact_name: row.contact_name,
      contact_title: row.contact_title,
      contact_email: row.contact_email,
      icp_tier: row.icp_tier,
      icp_score: row.icp_score,
      tech_stack_summary: (row.tech_stack || []).slice(0, 5).join(', '),
      hiring_active_jobs: row.hiring_intent?.active_count || 0,
      growth_departments: (row.hiring_intent?.growth_departments || []).join(', '),
      google_ads_active: row.google_ads?.has_active_ads ? 'YES' : 'NO',
      ai_email_subject: aiSubject,
      ai_email_body: aiBody,
      token_savings_pct: row.token_metrics?.token_reduction_pct || '97%',
      workflow_status: 'READY_FOR_OUTREACH',
      processed_at: new Date().toISOString()
    }
  });
}

return crmRecords;

// Prepare Disqualified Log for CRM Hygiene & 90-Day Follow-Up
const items = $input.all();
const deadLeads = [];

for (const item of items) {
  const row = item.json;
  deadLeads.push({
    json: {
      lead_domain: row.domain,
      company_name: row.company_name,
      contact_email: row.contact_email,
      icp_score: row.icp_score,
      disqualification_reasons: (row.disqualification_reasons || []).join(' | '),
      action_taken: 'EXCLUDED_FROM_LLM_SAVED_COST',
      recheck_recommended_date: new Date(Date.now() + 90 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
    }
  });
}

return deadLeads;
